{"content": "import pytest
import click
from click.testing import CliRunner


def test_invoke_mix_stderr_not_accepted():
    """``CliRunner.invoke`` should not accept a ``mix_stderr`` parameter.
    The ``mix_stderr`` setting is only used from ``CliRunner.__init__``.
    """

    @click.command()
    def cli():
        click.echo("test")

    runner = CliRunner()

    with pytest.raises(TypeError):
        runner.invoke(cli, mix_stderr=False)", "path": "tests/test_testing_mix_stderr.py"}
